      "content": "{\n  \"name\": \"managed-agents\",\n  \"version\": \"0.3.8\",\n  \"private\": true,\n  \"description\": \"Local-first, self-hosted AI agent runtime with Claude Managed Agents-style APIs, sandboxed sessions, memory, tools, audit, replay, and a local Console.\",\n  \"type\": \"module\",\n  \"homepage\": \"https://github.com/sandbaseai/sandbase-harness#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/sandbaseai/sandbase-harness.git\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./examples/deepseek-harness/cordis.yml\"\n    }\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/sandbaseai/sandbase-harness/issues\"\n  },\n  \"engines\": {\n    \"node\": \">=22\"\n  },\n  \"bin\": {\n    \"managed-agents\": \"dist/index.js\",\n    \"managed-agents-mcp\": \"dist/mcp/index.js\"\n  },\n  \"main\": \"./dist/index.js\",\n  \"types\": \"./dist/index.d.ts\",\n  \"files\": [\n    \"dist\",\n    \"docs\",\n    \"examples\",\n    \"!**/.managed-agents/logs\",\n    \"!**/.managed-agents/data.db*\",\n    \"!**/.managed-agents/files\",\n    \"!**/.managed-agents/cache\",\n    \"scripts\",\n    \"README.md\",\n    \"llms.txt\",\n    \"llms-install.md\",\n    \"CHANGELOG.md\",\n    \"CONTRIBUTING.md\",\n    \"LICENSE\"\n  ],\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./sdk\": {\n      \"types\": \"./dist/sdk.d.ts\",\n      \"import\": \"./dist/sdk.js\"\n    }\n  },\n  \"scripts\": {\n    \"dev\": \"tsx src/index.ts\",\n    \"dev:console\": \"vite --host 0.0.0.0 --config apps/console/vite.config.ts\",\n    \"build\": \"npm run build:runtime && npm run build:console\",\n    \"build:runtime\": \"tsdown\",\n    \"build:console\": \"npm run typecheck:console && vite build --config apps/console/vite.config.ts\",\n    \"prepare\": \"node scripts/prepare-install.mjs\",\n    \"start\": \"node dist/index.js\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"test:property\": \"vitest run tests/property\",\n    \"test:docs-examples\": \"vitest run tests/conformance/docs-examples\",\n    \"test:official-routes\": \"vitest run tests/conformance/official-route-coverage.test.ts tests/unit/official-routes.test.ts\",\n    \"test:e2e\": \"playwright test\",\n    \"test:docs-examples:update-snapshots\": \"node --import tsx tests/conformance/docs-examples/update-snapshots.ts\",\n    \"docs:compat\": \"node --import tsx scripts/render-compat-table.ts\",\n    \"lint\": \"npm run typecheck\",\n    \"typecheck\": \"npm run typecheck:src && npm run typecheck:tests && npm run typecheck:console\",\n    \"typecheck:src\": \"tsc --noEmit\",\n    \"typecheck:tests\": \"tsc --noEmit -p tsconfig.tests.json\",\n    \"typecheck:console\": \"tsc --noEmit -p apps/console/tsconfig.json\",\n    \"package:check\": \"npm pack --dry-run\",\n    \"smoke:release\": \"node scripts/smoke-release.mjs\",\n    \"release:check\": \"npm run typecheck && npm test && npm run build && npm run package:check && npm run smoke:release\",\n    \"format\": \"node -e \\\"console.log('No formatter configured yet.')\\\"\",\n    \"format:check\": \"node -e \\\"console.log('No formatter configured yet.')\\\"\"\n  },\n  \"keywords\": [\n    \"ai-agents\",\n    \"ai-agent-runtime\",\n    \"agent-runtime\",\n    \"managed-agents\",\n    \"claude-managed-agents\",\n    \"anthropic\",\n    \"mcp\",\n    \"mcp-tools\",\n    \"mcp-server\",\n    \"model-context-protocol\",\n    \"docker-mcp\",\n    \"cline\",\n    \"cursor\",\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"local-first\",\n    \"local-ai-agents\",\n    \"sandboxed-execution\",\n    \"agent-memory\",\n    \"credential-vaults\",\n    \"audit-log\",\n    \"session-replay\",\n    \"agent-console\",\n    \"skills\",\n    \"openai-compatible\",\n    \"ollama\",\n    \"vercel-ai-sdk\",\n    \"server-sent-events\",\n    \"agent-observability\",\n    \"agent-tools\",\n    \"ai-sandbox\",\n    \"developer-tools\",\n    \"typescript\",\n    \"sqlite\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"dependencies\": {\n    \"@ai-sdk/anthropic\": \"^4.0.72\",\n    \"@ai-sdk/openai\": \"^4.0.84\",\n    \"@hono/node-server\": \"^2.1.3\",\n    \"@modelcontextprotocol/sdk\": \"^1.31.0\",\n    \"ai\": \"^7.0.128\",\n    \"commander\": \"^15.0.0\",\n    \"escape-html\": \"1.0.3\",\n    \"hono\": \"^4.13.13\",\n    \"nanoid\": \"^6.0.1\",\n    \"prefix-safe-json\": \"0.5.0\",\n    \"react-markdown\": \"^10.1.0\",\n    \"remark-gfm\": \"^4.0.1\",\n    \"yaml\": \"^2.9.1\",\n    \"zod\": \"^4.6.5\"\n  },\n  \"devDependencies\": {\n    \"@anthropic-ai/sdk\": \"0.131.0\",\n    \"@babel/parser\": \"7.29.9\",\n    \"@base-ui/react\": \"^1.8.0\",\n    \"@fontsource-variable/geist-mono\": \"^5.3.0\",\n    \"@fontsource/ibm-plex-sans\": \"^5.3.0\",\n    \"@number-flow/react\": \"^0.6.2\",\n    \"@playwright/test\": \"1.63.0\",\n    \"@tailwindcss/vite\": \"^4.3.3\",\n    \"@testing-library/dom\": \"10.4.2\",\n    \"@testing-library/react\": \"16.3.3\",\n    \"@testing-library/user-event\": \"14.6.7\",\n    \"@types/escape-html\": \"1.0.4\",\n    \"@types/node\": \"^26.6.4\",\n    \"@types/react\": \"^19.3.0\",\n    \"@types/react-dom\": \"^19.3.0\",\n    \"@vitejs/plugin-react\": \"^6.0.0\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"fast-check\": \"^4.10.2\",\n    \"i18next\": \"^26.4.2\",\n    \"jsdom\": \"30.1.1\",\n    \"lucide-react\": \"^1.52.0\",\n    \"motion\": \"^13.5.1\",\n    \"react\": \"^19.3.0\",\n    \"react-dom\": \"^19.3.0\",\n    \"react-i18next\": \"^17.0.15\",\n    \"shadow-plugin\": \"^2.1.1\",\n    \"tailwind-merge\": \"^3.7.0\",\n    \"tailwindcss\": \"^4.3.3\",\n    \"tsdown\": \"^0.23.0\",\n    \"tsx\": \"^4.23.15\",\n    \"typescript\": \"^7.0.2\",\n    \"vite\": \"^8.3.2\",\n    \"vitest\": \"^5.0.3\"\n  }\n}\n"
